test('U1 converge controles y destacado con el sistema W2',async({page})=>{await page.goto('/w2/torneos');await expect(page.locator('.w2t-hero')).toBeVisible();await expect(page.locator('#pestanasTorneos')).toBeVisible();await expect(page.locator('#buscarTorneo')).toBeVisible();const controls=await page.locator('#buscarTorneo,.w2t-select-trigger,.w2t-open-only').evaluateAll(items=>items.map(item=>item.getBoundingClientRect().height));expect(Math.max(...controls)-Math.min(...controls)).toBeLessThanOrEqual(8);await page.goto('/w2/torneos?estado=FINALIZADO');await expect(page.locator('#pestanasTorneos [data-catalog-state="FINALIZADO"]')).toHaveClass(/active/);await expect(page.locator('#listaTorneos .state-finalizado').first()).toBeVisible();await expect(page.locator('#torneoDestacado')).toContainText('Torneo E2E');await expect(page.locator('#torneoDestacado')).toContainText('cupos disponibles');expect(await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth)).toBeLessThanOrEqual(1)});

test('U2 conserva la cabecera movil dentro del viewport',async({page})=>{await page.setViewportSize({width:390,height:844});await page.goto('/w2/torneos');const geometria=await page.locator('.w2-header .w2-nav').evaluate(nav=>{const n=nav.getBoundingClientRect(),brand=nav.querySelector('.w2-brand')?.getBoundingClientRect(),theme=nav.querySelector('.w2-theme-toggle')?.getBoundingClientRect(),menu=nav.querySelector('[data-w2-menu]')?.getBoundingClientRect();return {nav:[n.left,n.right],brand:[brand?.left||0,brand?.right||0],theme:[theme?.left||0,theme?.right||0],menu:[menu?.left||0,menu?.right||0],scroll:document.documentElement.scrollWidth,viewport:innerWidth}});for(const [,right] of [geometria.brand,geometria.theme,geometria.menu])expect(right).toBeLessThanOrEqual(geometria.viewport);for(const [left] of [geometria.brand,geometria.theme,geometria.menu])expect(left).toBeGreaterThanOrEqual(0);expect(geometria.scroll).toBeLessThanOrEqual(geometria.viewport);await expect(page.locator('[data-w2-menu]')).toContainText('Menú')});

