test('U2A compacta el hero y corrige acciones del catalogo',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');await expect(page.locator('#cerrarFiltrosTorneos')).toBeHidden();const posiciones=await page.evaluate(()=>{const header=document.querySelector('.w2-header')?.getBoundingClientRect(),hero=document.querySelector('.w2t-hero')?.getBoundingClientRect(),copy=document.querySelector('.w2t-hero-copy')?.getBoundingClientRect(),explorer=document.querySelector('.w2t-explorer')?.getBoundingClientRect();return {headerBottom:header?.bottom||0,heroHeight:hero?.height||0,copyTop:copy?.top||0,explorerTop:explorer?.top||0}});expect(posiciones.copyTop-posiciones.headerBottom).toBeLessThan(145);expect(posiciones.heroHeight).toBeLessThan(590);expect(posiciones.explorerTop).toBeLessThanOrEqual(900);const pestanas=page.locator('#pestanasTorneos [data-catalog-state]');await expect(pestanas).toHaveCount(3);const cantidades=await pestanas.evaluateAll(items=>items.map(item=>Number(item.getAttribute('data-count'))));expect(cantidades.every(Number.isFinite)).toBe(true);const indiceVacio=cantidades.findIndex(total=>total===0);if(indiceVacio>=0){const pestanaVacia=pestanas.nth(indiceVacio);await pestanaVacia.click();const vacio=page.locator('#vaciarFiltrosTorneos[data-empty-action="navigate"]');await expect(vacio).toBeVisible();await expect(vacio).toContainText(/Ver torneos finalizados|Ver próximos torneos|Ver competencias en curso/);const destino=await vacio.getAttribute('data-empty-state');expect(destino).toMatch(/PROXIMO|EN_CURSO|FINALIZADO/);await vacio.click();await expect(page.locator('#pestanasTorneos [data-catalog-state="'+destino+'"]')).toHaveClass(/active/);await expect(page).toHaveURL(new RegExp('estado='+destino));await expect(page.locator('#listaTorneos .w2t-card').first()).toBeVisible()}else{for(let indice=0;indice<3;indice++){await pestanas.nth(indice).click();await expect(page.locator('#listaTorneos .w2t-card').first()).toBeVisible()}}});

test('U2A conserva el cierre funcional de filtros solo en movil',async({page})=>{await page.setViewportSize({width:390,height:844});await page.goto('/w2/torneos');const abrir=page.locator('#abrirFiltrosTorneos'),cerrar=page.locator('#cerrarFiltrosTorneos'),panel=page.locator('#panelFiltrosTorneos');await abrir.click();await expect(panel).toHaveClass(/open|filters-visible/);await expect(cerrar).toBeVisible();await cerrar.click();await expect(panel).not.toHaveClass(/open|filters-visible/);await expect(abrir).toBeFocused()});

test('U2B estabiliza densidad y contexto del catalogo',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');const contexto=page.locator('#contextoCatalogoTorneos');await expect(contexto).toBeVisible();await expect(contexto).toContainText(/competencias|Actividad competitiva|Historial competitivo/i);const panel=page.locator('#panelFiltrosTorneos');const alturaInicial=await panel.evaluate(e=>e.getBoundingClientRect().height);await page.locator('#filtroInscripcion').check();const alturaFiltrada=await panel.evaluate(e=>e.getBoundingClientRect().height);expect(Math.abs(alturaFiltrada-alturaInicial)).toBeLessThanOrEqual(1);await expect(page.locator('#limpiarFiltrosTorneos')).toBeHidden();await expect(page.locator('#limpiarFiltrosTorneosInline')).toBeVisible();const hero=await page.locator('.w2t-hero').evaluate(e=>e.getBoundingClientRect().height);expect(hero).toBeLessThan(570)});

test('U2B conserva controles de limpieza dentro del panel movil',async({page})=>{await page.setViewportSize({width:390,height:844});await page.goto('/w2/torneos');await expect(page.locator('#contextoCatalogoTorneos')).toBeHidden();const abrir=page.locator('#abrirFiltrosTorneos'),panel=page.locator('#panelFiltrosTorneos');await abrir.click();await page.locator('#filtroInscripcion').check();await expect(page.locator('#aplicarFiltrosTorneos')).toBeVisible();await page.locator('#aplicarFiltrosTorneos').click();await expect(panel).not.toHaveClass(/open|filters-visible/);await expect(page.locator('#chipsFiltrosTorneos')).toContainText('Inscripción abierta');await abrir.click();await expect(page.locator('#limpiarFiltrosTorneos')).toBeVisible()});


test('U2C alinea los controles equivalentes del panel',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');const cajas=await page.locator('#panelFiltrosTorneos>.w2t-field .w2t-select-trigger,#panelFiltrosTorneos>.w2t-open-only').evaluateAll(items=>items.map(item=>{const r=item.getBoundingClientRect();return {top:Math.round(r.top),bottom:Math.round(r.bottom),height:Math.round(r.height)}}));expect(cajas).toHaveLength(3);expect(Math.max(...cajas.map(caja=>caja.top))-Math.min(...cajas.map(caja=>caja.top))).toBeLessThanOrEqual(1);expect(Math.max(...cajas.map(caja=>caja.bottom))-Math.min(...cajas.map(caja=>caja.bottom))).toBeLessThanOrEqual(1);expect(cajas.every(caja=>Math.abs(caja.height-52)<=1)).toBe(true)});


test('U2D ubica las tres etiquetas sobre una misma fila',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');const datos=await page.evaluate(()=>{const panel=document.querySelector('#panelFiltrosTorneos');const rama=document.querySelector('#panelFiltrosTorneos>.w2t-field>span');const formato=document.querySelectorAll('#panelFiltrosTorneos>.w2t-field>span')[1];const disponibilidad=document.querySelector('#panelFiltrosTorneos>.w2t-open-only');const r3=disponibilidad?getComputedStyle(disponibilidad,'::before'):null;return {alto:Math.round(panel?.getBoundingClientRect().height||0),etiquetas:[rama?.textContent?.trim(),formato?.textContent?.trim(),r3?.content?.replaceAll('"','')]}});expect(datos.alto).toBe(112);expect(datos.etiquetas).toEqual(['Rama','Formato','DISPONIBILIDAD'])});


test('U2E mantiene el panel movil util en viewports reducidos',async({page})=>{for(const viewport of [{width:390,height:844},{width:320,height:760},{width:320,height:640}]){await page.setViewportSize(viewport);await page.goto('/w2/torneos');await page.locator('#abrirFiltrosTorneos').click();const panel=page.locator('#panelFiltrosTorneos'),aplicar=page.locator('#aplicarFiltrosTorneos'),cerrar=page.locator('#cerrarFiltrosTorneos');await expect(panel).toBeVisible();await expect(cerrar).toBeVisible();await expect(aplicar).toBeVisible();const geometria=await panel.evaluate(element=>{const r=element.getBoundingClientRect();return {top:r.top,bottom:r.bottom,height:r.height,viewport:innerHeight,scrollHeight:element.scrollHeight,clientHeight:element.clientHeight}});expect(geometria.top).toBeGreaterThanOrEqual(0);expect(geometria.bottom).toBeLessThanOrEqual(geometria.viewport+1);expect(geometria.height).toBeLessThanOrEqual(geometria.viewport);await cerrar.click();await expect(page.locator('#abrirFiltrosTorneos')).toBeFocused()}});

test('C1D separa tabla y tarjetas del centro competitivo',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');if(!await page.locator('#listaTorneos .catalog-open').count())await page.locator('#pestanasTorneos [data-catalog-state="FINALIZADO"]').click();await page.locator('#listaTorneos .catalog-open').first().click();await page.locator('[data-detail-tab="categorias"]').click();await page.locator('[data-open-competition]').first().click();await page.locator('[data-f4-view="posiciones"]').click();await expect(page.locator('.f4-table-desktop')).toBeVisible();await expect(page.locator('.f4-positions-mobile')).toBeHidden();await expect(page.locator('.w2cc-center>p.sr-only')).toHaveCSS('position','fixed');await expect(page.locator('.w2cc-center>p.sr-only')).toHaveCSS('width','1px');const liveBox=await page.locator('.w2cc-center>p.sr-only').boundingBox();expect(liveBox?.x??0).toBeLessThan(-9000);await page.setViewportSize({width:390,height:844});await expect(page.locator('.f4-table-desktop')).toBeHidden();await expect(page.locator('.f4-positions-mobile')).toBeVisible()});

test('C1D conserva nombres de fases y carruseles moviles completos',async({page})=>{await page.setViewportSize({width:390,height:844});await page.goto('/w2/torneos');if(!await page.locator('#listaTorneos .catalog-open').count())await page.locator('#pestanasTorneos [data-catalog-state="FINALIZADO"]').click();await page.locator('#listaTorneos .catalog-open').first().click();await page.locator('[data-detail-tab="categorias"]').click();await page.locator('[data-open-competition]').first().click();await activarVistaCentro(page,'partidos');await expect(page.locator('.f4-phase-section>header h4>span').first()).toBeVisible();await activarVistaCentro(page,'cuadro');await expect(page.locator('.f4-round.mobile-active')).toBeVisible();await expect(page.locator('.w2cc-center>p.sr-only')).toHaveCSS('position','fixed');await expect(page.locator('.w2cc-center>p.sr-only')).toHaveCSS('width','1px');const liveBox=await page.locator('.w2cc-center>p.sr-only').boundingBox();expect(liveBox?.x??0).toBeLessThan(-9000);for(const selector of ['.f4-nav','.f4-round-tabs']){const g=await page.locator(selector).evaluate(e=>{const r=e.getBoundingClientRect();return {left:r.left,right:r.right,viewport:innerWidth}});expect(g.left).toBeGreaterThanOrEqual(-1);expect(g.right).toBeLessThanOrEqual(g.viewport+1)}});


test('C1D1 mantiene metricas y tabla sin superficies residuales',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');if(!await page.locator('#listaTorneos .catalog-open').count())await page.locator('#pestanasTorneos [data-catalog-state="FINALIZADO"]').click();await page.locator('#listaTorneos .catalog-open').first().click();await page.locator('[data-detail-tab="categorias"]').click();await page.locator('[data-open-competition]').first().click();const facts=page.locator('.f4-hero-facts>span');await expect(facts).toHaveCount(3);const tops=await facts.evaluateAll(items=>items.map(item=>Math.round(item.getBoundingClientRect().top)));expect(new Set(tops).size).toBe(1);await page.locator('.f4-nav [data-f4-view="posiciones"]').click();const anchos=await page.evaluate(()=>{const wrap=document.querySelector('.f4-table-wrap')?.getBoundingClientRect(),table=document.querySelector('.f4-table-wrap table')?.getBoundingClientRect();return {wrap:Math.round(wrap?.width||0),table:Math.round(table?.width||0)}});expect(Math.abs(anchos.wrap-anchos.table)).toBeLessThanOrEqual(2)});

test('C1D13 valida la banda estadistica autoritativa',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');if(!await page.locator('#listaTorneos .catalog-open').count())await page.locator('#pestanasTorneos [data-catalog-state="FINALIZADO"]').click();await page.locator('#listaTorneos .catalog-open').first().click();await page.locator('[data-detail-tab="categorias"]').click();await page.locator('[data-open-competition]').first().click();await expect(page.locator('.w2cc-center')).toBeVisible();const datos=await page.locator('.f4-hero-facts>span').evaluateAll((items:HTMLElement[])=>items.map((item:HTMLElement)=>{const r=item.getBoundingClientRect(),label=item.querySelector<HTMLElement>('small'),value=item.querySelector<HTMLElement>('b');return {top:Math.round(r.top),width:Math.round(r.width),height:Math.round(r.height),labelSize:label?parseFloat(getComputedStyle(label).fontSize):0,valueSize:value?parseFloat(getComputedStyle(value).fontSize):0}}));expect(new Set(datos.map((item:{top:number})=>item.top)).size).toBe(1);expect(datos.map((item:{width:number})=>item.width)).toEqual([98,128,140]);expect(datos.every((item:{height:number})=>item.height===44)).toBe(true);expect(datos.every((item:{labelSize:number})=>item.labelSize>=10.3)).toBe(true);expect(datos.every((item:{valueSize:number})=>item.valueSize>=18.8)).toBe(true)});

test('C1D13 aplica rojo interactivo y centra el cierre de la llave',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos');if(!await page.locator('#listaTorneos .catalog-open').count())await page.locator('#pestanasTorneos [data-catalog-state="FINALIZADO"]').click();await page.locator('#listaTorneos .catalog-open').first().click();await page.locator('[data-detail-tab="categorias"]').click();await page.locator('[data-open-competition]').first().click();await page.locator('.f4-nav [data-f4-view="cuadro"]').click();await page.locator('[data-f4-full-bracket]').click();const modal=page.locator('#modalCuadroTorneo');await expect(modal).toBeVisible();const controles=modal.locator('.bracket-v48-toolbar button');await expect(controles).toHaveCount(3);for(let i=0;i<3;i++){const control=controles.nth(i);await control.hover();const estilo=await control.evaluate((element:HTMLElement)=>{const s=getComputedStyle(element);return {border:s.borderColor,background:s.backgroundColor,shadow:s.boxShadow}});expect(estilo.border).toBe('rgb(239, 64, 81)');expect(estilo.background).toBe('rgb(33, 16, 20)');expect(estilo.shadow).not.toContain('105, 202, 152')}const cerrar=modal.locator('.bracket-v41-close').first();const cierre=await cerrar.evaluate((element:HTMLElement)=>{const s=getComputedStyle(element),p=getComputedStyle(element,'::before'),r=element.getBoundingClientRect();return {display:s.display,width:Math.round(r.width),height:Math.round(r.height),padding:s.padding,content:p.content,lineHeight:p.lineHeight}});expect(cierre.display).toBe('block');expect(cierre.width).toBe(38);expect(cierre.height).toBe(38);expect(cierre.padding).toBe('0px');expect(cierre.content).toBe('""');expect(cierre.lineHeight).toBe('0px');const cruz=await cerrar.evaluate((element:HTMLElement)=>{const r=element.getBoundingClientRect(),a=getComputedStyle(element,'::before'),b=getComputedStyle(element,'::after');return {beforeTop:a.top,beforeLeft:a.left,afterTop:b.top,afterLeft:b.left,beforeWidth:parseFloat(a.width),afterWidth:parseFloat(b.width),centerX:r.width/2,centerY:r.height/2}});expect(Math.abs(parseFloat(cruz.beforeLeft)-cruz.centerX)).toBeLessThanOrEqual(1);expect(Math.abs(parseFloat(cruz.beforeTop)-cruz.centerY)).toBeLessThanOrEqual(1);expect(Math.abs(parseFloat(cruz.afterLeft)-cruz.centerX)).toBeLessThanOrEqual(1);expect(Math.abs(parseFloat(cruz.afterTop)-cruz.centerY)).toBeLessThanOrEqual(1);expect(cruz.beforeWidth).toBe(15);expect(cruz.afterWidth).toBe(15)});

test('D3 integra hero metricas y navegacion editorial',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1&seccion=informacion');const resumen=page.locator('.w2td-summary');await expect(resumen).toBeVisible();const g=await resumen.evaluate(element=>{const r=element.getBoundingClientRect(),spans=[...element.querySelectorAll('span')].map(item=>getComputedStyle(item));return {width:Math.round(r.width),gaps:getComputedStyle(element).gap,borders:spans.slice(1).map(style=>style.borderLeftWidth)}});expect(g.width).toBeGreaterThan(350);expect(g.gaps).toBe('0px');const tabs=page.locator('.w2td-tabs');expect(await tabs.evaluate(element=>Math.round(element.getBoundingClientRect().width))).toBeLessThanOrEqual(980);const metricas=page.locator('.w2td-metrics>div');expect((await metricas.evaluateAll(items=>items.map(item=>Math.round(item.getBoundingClientRect().height)))).every(value=>value<=70)).toBeTruthy()});

test('D3 compacta categoria unica y anima acciones',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1&seccion=categorias');const tarjeta=page.locator('.w2td-category-grid.results-1 .w2td-category').first();if(await tarjeta.count()){const r=await tarjeta.evaluate(element=>{const b=element.getBoundingClientRect(),s=getComputedStyle(element);return {display:s.display,height:Math.round(b.height),columns:s.gridTemplateColumns}});expect(r.display).toBe('grid');expect(r.height).toBeLessThan(300);expect(r.columns.split(' ').length).toBeGreaterThanOrEqual(3);const boton=tarjeta.locator('footer button').first();await boton.hover();const transform=await boton.evaluate(element=>getComputedStyle(element).transform);expect(transform).not.toBe('none')}await page.goto('/w2/torneos?torneo=1&seccion=reglamento');const volver=page.locator('.w2td-document-empty button');if(await volver.count()){await volver.hover();expect(await volver.evaluate(element=>getComputedStyle(element).transform)).not.toBe('none')}});

