test('D4 aplica contorno rojo y microinteraccion a las acciones contextuales',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1');const botones=page.locator('.w2td-topbar button');await expect(botones).toHaveCount(2);for(let i=0;i<2;i++){const boton=botones.nth(i);const inicial=await boton.evaluate(element=>getComputedStyle(element).borderColor);expect(inicial).toBe('rgb(48, 58, 65)');await boton.hover();const hover=await boton.evaluate(element=>{const s=getComputedStyle(element);return {border:s.borderColor,transform:s.transform,shadow:s.boxShadow}});expect(hover.border).toBe('rgb(239, 64, 81)');expect(hover.transform).not.toBe('none');expect(hover.shadow).not.toBe('none')}});

test('D4 conserva animaciones en atajos y reglamento',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1&seccion=categorias');const resultado=page.locator('.w2td-category footer button').first();if(await resultado.count()){await resultado.hover();expect(await resultado.evaluate(element=>getComputedStyle(element).transform)).not.toBe('none')}await page.goto('/w2/torneos?torneo=1&seccion=reglamento');const volver=page.locator('.w2td-document-empty button');if(await volver.count()){await volver.hover();expect(await volver.evaluate(element=>getComputedStyle(element).transform)).not.toBe('none')}});

test('D5 separa punto numero y contenido del recorrido',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1&seccion=informacion');const pasos=page.locator('.w2td-timeline li');await expect(pasos).toHaveCount(3);for(let i=0;i<3;i++){const paso=pasos.nth(i);const g=await paso.evaluate(element=>{const r=element.getBoundingClientRect(),n=element.querySelector('i')!.getBoundingClientRect(),p=getComputedStyle(element,'::before'),b=element.querySelector('b')!.getBoundingClientRect();return {pointX:r.left+parseFloat(p.left),numberLeft:n.left,titleLeft:b.left,numberRight:n.right}});expect(g.numberLeft-g.pointX).toBeGreaterThanOrEqual(8);expect(g.titleLeft-g.numberRight).toBeGreaterThanOrEqual(4)}});

test('D5 convierte el atajo del hero en accion contorneada',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1');const cta=page.locator('.w2td-actions button.primary');await expect(cta).toBeVisible();const reposo=await cta.evaluate(element=>{const s=getComputedStyle(element);return {border:s.borderColor,background:s.backgroundColor}});expect(reposo.border).toBe('rgba(239, 64, 81, 0.58)');expect(reposo.background).not.toBe('rgb(215, 25, 45)');await cta.hover();expect(await cta.evaluate(element=>getComputedStyle(element).transform)).not.toBe('none')});

test('D5 contiene la cabecera sin banda exterior',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1');await page.evaluate(()=>scrollTo(0,700));const datos=await page.locator('.w2-header').evaluate(element=>{const s=getComputedStyle(element),nav=element.querySelector<HTMLElement>('.w2-nav')!,r=nav.getBoundingClientRect();return {background:s.backgroundColor,image:s.backgroundImage,shadow:s.boxShadow,navLeft:Math.round(r.left),navRight:Math.round(r.right),viewport:innerWidth}});expect(datos.background).toBe('rgba(0, 0, 0, 0)');expect(datos.image).toBe('none');expect(datos.shadow).toBe('none');expect(datos.navLeft).toBeGreaterThan(0);expect(datos.navRight).toBeLessThan(datos.viewport)});

test('D6 iguala acciones contextuales con el centro competitivo',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1');const botones=page.locator('.w2td-topbar button');await expect(botones).toHaveCount(2);for(let i=0;i<2;i++){const boton=botones.nth(i);const reposo=await boton.evaluate(element=>{const s=getComputedStyle(element);return {border:s.borderColor,background:s.backgroundColor}});expect(reposo.border).toBe('rgb(48, 58, 65)');expect(reposo.background).not.toBe('rgb(33, 16, 20)');await boton.hover();const hover=await boton.evaluate(element=>{const s=getComputedStyle(element);return {border:s.borderColor,background:s.backgroundColor,transform:s.transform}});expect(hover.border).toBe('rgb(239, 64, 81)');expect(hover.background).toBe('rgb(33, 16, 20)');expect(hover.transform).not.toBe('none')}});

test('D7 unifica acciones del detalle y centro competitivo',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=2&seccion=categorias');const externas=page.locator('.w2td-topbar button');await expect(externas).toHaveCount(2);const exterior=await externas.first().evaluate(element=>{const s=getComputedStyle(element),r=element.getBoundingClientRect();return {height:Math.round(r.height),font:s.fontSize,weight:s.fontWeight,radius:s.borderRadius,padding:s.padding}});await page.locator('[data-open-competition]').first().click();const internas=page.locator('.f4-topbar button');await expect(internas).toHaveCount(2);const interior=await internas.first().evaluate(element=>{const s=getComputedStyle(element),r=element.getBoundingClientRect();return {height:Math.round(r.height),font:s.fontSize,weight:s.fontWeight,radius:s.borderRadius,padding:s.padding}});expect(interior).toEqual(exterior);const posiciones=await page.locator('.f4-topbar button').evaluateAll(items=>items.map(item=>Math.round(item.getBoundingClientRect().left)));expect(posiciones[1]-posiciones[0]).toBeLessThan(260)});

test('D8 alinea acciones con el inicio del hero exterior e interior',async({page})=>{await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=2&seccion=categorias');let geometria=await page.evaluate(()=>{const top=document.querySelector('.w2td-topbar')?.getBoundingClientRect(),hero=document.querySelector('.w2td-hero')?.getBoundingClientRect();return {top:Math.round(top?.left||0),hero:Math.round(hero?.left||0)}});expect(Math.abs(geometria.top-geometria.hero)).toBeLessThanOrEqual(1);await page.locator('[data-open-competition]').first().click();geometria=await page.evaluate(()=>{const top=document.querySelector('.f4-topbar')?.getBoundingClientRect(),hero=document.querySelector('.f4-hero')?.getBoundingClientRect();return {top:Math.round(top?.left||0),hero:Math.round(hero?.left||0)}});expect(Math.abs(geometria.top-geometria.hero)).toBeLessThanOrEqual(1)});

test('D10 replica exactamente la cabecera oscura de Inicio',async({page})=>{await page.emulateMedia({colorScheme:'dark'});await page.addInitScript(()=>localStorage.setItem('w2-theme','dark'));await page.setViewportSize({width:1440,height:900});await page.goto('/w2/torneos?torneo=1');await page.evaluate(()=>{document.documentElement.dataset.theme='dark';document.documentElement.classList.remove('light')});const datos=await page.locator('.w2-header .w2-nav').evaluate(element=>{const s=getComputedStyle(element),p=getComputedStyle(element,'::before'),a=getComputedStyle(element,'::after');return {nav:{overflow:s.overflow,isolation:s.isolation,border:s.border,borderRadius:s.borderRadius,background:s.backgroundImage,shadow:s.boxShadow,filter:s.backdropFilter},before:{display:p.display,position:p.position,inset:p.inset,borderRadius:p.borderRadius,background:p.backgroundImage,opacity:p.opacity,content:p.content,zIndex:p.zIndex},after:{display:a.display,content:a.content}}});expect(datos.nav.overflow).toBe('visible');expect(datos.nav.isolation).toBe('auto');expect(datos.nav.border).toBe('1px solid rgba(151, 168, 181, 0.52)');expect(datos.nav.borderRadius).toBe('25px');expect(datos.nav.background).toContain('rgba(8, 10, 13, 0.96)');expect(datos.nav.background).toContain('rgba(8, 10, 13, 0.9)');expect(datos.nav.shadow).toBe('rgba(0, 0, 0, 0.3) 0px 18px 48px 0px');expect(datos.nav.filter).toContain('blur(22px)');expect(datos.before.display).toBe('block');expect(datos.before.position).toBe('absolute');expect(datos.before.inset).toBe('-1px');expect(datos.before.borderRadius).toBe('25px');expect(datos.before.background).toContain('linear-gradient(110deg');expect(datos.before.background).toContain('rgb(239, 51, 76)');expect(datos.before.background).toContain('rgba(203, 217, 226, 0.46)');expect(datos.before.opacity).toBe('0.9');expect(datos.before.content).toBe('""');expect(datos.before.zIndex).toBe('-1');expect(datos.after.display).toBe('none');expect(datos.after.content).toBe('none')});

test('H1B comparte la cabecera exacta entre rutas W2',async({page})=>{await page.emulateMedia({colorScheme:'dark'});await page.addInitScript(()=>localStorage.setItem('w2-theme','dark'));await page.setViewportSize({width:1440,height:900});const rutas=['/w2/','/reservar','/w2/torneos','/w2/rankings','/w2/comunidad'];let referencia:any=null;for(const ruta of rutas){await page.goto(ruta);const nav=page.locator('.w2-header .w2-nav');await expect(nav).toBeVisible();const datos=await nav.evaluate(element=>{const s=getComputedStyle(element),p=getComputedStyle(element,'::before'),a=getComputedStyle(element,'::after');return {borderTop:s.borderTop,borderRight:s.borderRight,borderBottom:s.borderBottom,borderLeft:s.borderLeft,borderRadius:s.borderRadius,background:s.backgroundImage,shadow:s.boxShadow,filter:s.backdropFilter,overflow:s.overflow,isolation:s.isolation,before:{display:p.display,position:p.position,inset:p.inset,radius:p.borderRadius,background:p.backgroundImage,opacity:p.opacity,content:p.content,zIndex:p.zIndex},after:{display:a.display,content:a.content}}});if(!referencia)referencia=datos;else expect(datos).toEqual(referencia)}});

test('H1 no pinta superficie exterior alrededor de la cabecera',async({page})=>{await page.setViewportSize({width:1440,height:900});for(const ruta of ['/reservar','/w2/torneos','/w2/rankings','/w2/comunidad']){await page.goto(ruta);const datos=await page.locator('.w2-header').evaluate(element=>{const s=getComputedStyle(element),a=getComputedStyle(element,'::before'),b=getComputedStyle(element,'::after');return {background:s.backgroundImage,color:s.backgroundColor,shadow:s.boxShadow,before:a.display,after:b.display}});expect(datos.background).toBe('none');expect(datos.color).toBe('rgba(0, 0, 0, 0)');expect(datos.shadow).toBe('none');expect(datos.before).toBe('none');expect(datos.after).toBe('none')}});

test('H1B elimina desenfoque y contorno exterior en rutas internas',async({page})=>{await page.setViewportSize({width:1440,height:900});for(const ruta of ['/reservar','/w2/torneos','/w2/rankings','/w2/comunidad']){await page.goto(ruta);const datos=await page.locator('.w2-header').evaluate(element=>{const s=getComputedStyle(element);return {background:s.backgroundImage,color:s.backgroundColor,shadow:s.boxShadow,filter:s.backdropFilter,borders:[s.borderTopWidth,s.borderRightWidth,s.borderBottomWidth,s.borderLeftWidth]}});expect(datos.background).toBe('none');expect(datos.color).toBe('rgba(0, 0, 0, 0)');expect(datos.shadow).toBe('none');expect(datos.filter).toBe('none');expect(datos.borders).toEqual(['0px','0px','0px','0px'])}});

test('H1C mantiene los cuatro bordes identicos en cada ruta',async({page})=>{await page.emulateMedia({colorScheme:'dark'});await page.addInitScript(()=>localStorage.setItem('w2-theme','dark'));await page.setViewportSize({width:1440,height:900});for(const ruta of ['/w2/','/reservar','/w2/torneos','/w2/rankings','/w2/comunidad']){await page.goto(ruta);const bordes=await page.locator('.w2-header .w2-nav').evaluate(element=>{const s=getComputedStyle(element);return [s.borderTop,s.borderRight,s.borderBottom,s.borderLeft]});expect(bordes).toEqual(['1px solid rgba(151, 168, 181, 0.52)','1px solid rgba(151, 168, 181, 0.52)','1px solid rgba(151, 168, 181, 0.52)','1px solid rgba(151, 168, 181, 0.52)'])}});

/* H2F · STICKY PREMIUM ALINEADO A CABECERA */
test('H2F iguala el ancho del sticky competitivo con la cabecera',async({page})=>{await page.setViewportSize({width:1440,height:900});await abrirCentro(page,'partidos');const medidas=await page.evaluate(()=>{const h=document.querySelector<HTMLElement>('.w2-header .w2-nav')!.getBoundingClientRect(),n=document.querySelector<HTMLElement>('.w2cc-center .f4-nav')!.getBoundingClientRect();return {headerWidth:h.width,navWidth:n.width,left:Math.abs(h.left-n.left),right:Math.abs(h.right-n.right),top:parseFloat(getComputedStyle(document.querySelector<HTMLElement>('.w2cc-center .f4-nav')!).top)}});expect(Math.abs(medidas.headerWidth-medidas.navWidth)).toBeLessThanOrEqual(1);expect(medidas.left).toBeLessThanOrEqual(1);expect(medidas.right).toBeLessThanOrEqual(1);expect(medidas.top).toBe(97)});
